const items=[['Canon PIXMA G5070','print','Máy in phun màu','G5070-01.png'],['Canon PIXMA G1010','print','Máy in phun màu','G1010-01.png'],['Canon imageCLASS LBP121dn','print','Máy in laser','121dn-01.png'],['Máy ảnh Canon EOS','camera','Thiết bị hình ảnh','may-chup-anh.jpg'],['Máy quay phim Canon','camera','Thiết bị hình ảnh','may-quay-phim.jpg'],['Máy scan Canon','other','Thiết bị văn phòng','may-scan.jpg'],['Máy chiếu','other','Thiết bị trình chiếu','may-chieu.jpg']];const cats=[['Máy in','print','may-in.jpg'],['Máy photocopy','print','may-photocopy.jpg'],['Máy ảnh','camera','may-chup-anh.jpg'],['Máy quay phim','camera','may-quay-phim.jpg'],['Máy scan','other','may-scan.jpg'],['Máy chiếu','other','may-chieu.jpg']];const grid=document.querySelector('#grid'),dialog=document.querySelector('dialog');function filter(type){grid.replaceChildren();items.filter(p=>type==='all'||p[1]===type).slice(0,type==='all'?4:8).forEach(p=>{const b=document.createElement('button');b.className='product';b.innerHTML=`<small class="tag">KHÁM PHÁ</small><img loading="lazy" src="assets/${p[3]}" alt="${p[0]}"><small>${p[2]}</small><h4>${p[0]}</h4><span class="more">Xem sản phẩm <b>↗</b></span>`;b.onclick=()=>{document.querySelector('#detail-img').src='assets/'+p[3];document.querySelector('#detail-img').alt=p[0];document.querySelector('#detail-name').textContent=p[0];dialog.showModal()};grid.append(b)});document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===type))}cats.forEach(c=>{const b=document.createElement('button');b.className='category';b.innerHTML=`<img src="assets/${c[2]}" alt=""><span>${c[0]} <i>↗</i></span>`;b.onclick=()=>{filter(c[1]);document.querySelector('.products-heading').scrollIntoView({behavior:'smooth'})};document.querySelector('#categories').append(b)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.filter));document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});filter('all');
